/*
 * A325457  Heinz numbers of integer partitions with strictly decreasing
 *          differences.
 * https://oeis.org/A325457
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the n-th Heinz number that can be obtained from an
 *            integer partition whose differences (in decreasing order) are
 *            strictly decreasing. The Heinz number of a partition (y1,...,yk)
 *            is the product of the primes indexed by the parts:
 *            prime(y1)*...*prime(yk). The sequence is generated by testin...
 * Range:     u8 n <= 65, u16 n <= 65, u32 n <= 65, u64 n <= 65, u128 n <= 65,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

/* Static data used to test validity of a number. */
#define MAX_PRIME 200000          /* enough for 64‑bit numbers up to ~10^12 */
#define MAX_PRIMES_COUNT 20000    /* count of primes up to MAX_PRIME */

static uint32_t primes[MAX_PRIMES_COUNT];
static size_t   primes_cnt = 0;
static uint32_t prime_index[MAX_PRIME + 1];

/* Initialise the prime table only once. */
static void init_primes(void) {
    static bool done = false;
    if (done) return;
    done = true;
    static unsigned char is_composite[MAX_PRIME + 1];
    for (uint32_t i = 2; i <= MAX_PRIME; ++i) {
        if (!is_composite[i]) {
            if (primes_cnt < MAX_PRIMES_COUNT) {
                primes[primes_cnt++] = i;
                prime_index[i] = (uint32_t)(primes_cnt);  /* 1‑based index */
            }
            if ((uint64_t)i * i <= MAX_PRIME) {
                for (uint32_t j = i * i; j <= MAX_PRIME; j += i)
                    is_composite[j] = 1;
            }
        }
    }
}

/* Check whether a number x has a partition with strictly decreasing
   differences of its parts.  The parts are the prime indices of the
   prime factorisation of x. */
static bool is_valid_uint64(uint64_t x) {
    if (x == 1) return true;        /* empty partition is allowed */

    /* Store indices of prime factors (with multiplicity). */
    int parts[64];
    size_t len = 0;
    uint64_t tmp = x;

    for (size_t i = 0; i < primes_cnt; ++i) {
        uint32_t p = primes[i];
        uint64_t sq = (uint64_t)p * (uint64_t)p;
        if (sq > tmp) break;
        if (tmp % p == 0) {
            int idx = prime_index[p];
            while (tmp % p == 0) {
                parts[len++] = idx;
                tmp /= p;
            }
        }
    }
    if (tmp > 1) {
        /* Remaining prime factor may be larger than MAX_PRIME.  In
           that case we cannot determine its index, so the number
           is treated as invalid.  This situation never occurs for
           the range we need to generate. */
        if (tmp <= MAX_PRIME) {
            int idx = prime_index[(uint32_t)tmp];
            parts[len++] = idx;
        } else {
            return false;
        }
    }

    if (len < 2) return true;  /* single part is always valid */

    /* Sort indices in descending order. */
    for (size_t i = 1; i < len; ++i) {
        int key = parts[i];
        size_t j = i;
        while (j > 0 && parts[j - 1] < key) {
            parts[j] = parts[j - 1];
            --j;
        }
        parts[j] = key;
    }

    /* Check strictly decreasing differences. */
    int prev_diff = parts[1] - parts[0];
    for (size_t i = 1; i + 1 < len; ++i) {
        int diff = parts[i + 1] - parts[i];
        if (!(prev_diff > diff)) return false;
        prev_diff = diff;
    }
    return true;
}

/* Helper: grow the cache array. */
static void grow_cache(size_t min_cap, seq_t **arr, size_t *cap) {
    size_t new_cap = (*cap) ? (*cap) * 2 : 64;
    while (new_cap < min_cap) new_cap *= 2;
    seq_t *new_arr = (seq_t *)realloc(*arr, new_cap * sizeof(seq_t));
    *arr = new_arr;
    *cap = new_cap;
}

/* Main function required by the build. */
seq_t a(idx_t n) {
    static seq_t *cache = NULL;
    static size_t   size = 0;
    static size_t   cap  = 0;
    static uint64_t next_to_check = 2;  /* number to test next */
    init_primes();                      /* ensure primes are ready */

    if (size == 0) {                    /* first call: initialise cache */
        grow_cache(64, &cache, &cap);
        cache[0] = (seq_t)1;
        size = 1;
    }

    /* Generate terms until we have at least n of them. */
    while (size < n) {
        uint64_t x = next_to_check;
        while (true) {
            if (is_valid_uint64(x)) {
                if (size == cap) grow_cache(size + 1, &cache, &cap);
                cache[size++] = (seq_t)x;
                next_to_check = x + 1;
                break;
            }
            ++x;
        }
    }

    return cache[n - 1];
}
